{
  "candidates": [
    {
      "subpart": "PPPP",
      "title": "National Emission Standards for Hazardous Air Pollutants: Surface Coating of Plastic Parts and Products",
      "criteria": [
        {
          "criterion": "If the operation involves the application of a material (a \"coating\") to plastic parts or products (including associated activities such as surface preparation, cleaning, mixing, and storage), then the operation falls within the source category covered by this subpart.",
          "citations": [
            "40 CFR 63.4481(a)(1)",
            "40 CFR 63.4581"
          ]
        },
        {
          "criterion": "If the material applied is an adhesive (a chemical substance applied for the purpose of bonding two surfaces together), then that application is treated as a coating for purposes of this subpart (subject to specific exclusions in the definitions).",
          "citations": [
            "40 CFR 63.4581",
            "40 CFR 63.4481(a)(1)"
          ]
        },
        {
          "criterion": "If you use 378 liters (100 gallons) per year or more of coatings that contain hazardous air pollutants (HAP) in the surface coating of plastic parts and products and the source is a major source (≥10 tpy single HAP or ≥25 tpy total HAP), then you are subject to this subpart.",
          "citations": [
            "40 CFR 63.4481(b)"
          ]
        },
        {
          "criterion": "If your surface coating or coating operation meets any of the exemption criteria listed in § 63.4481(c) (e.g., uses only coatings/thinners/cleaning materials that contain no organic HAP, research/laboratory or hobby shop activities, specified product-specific exclusions), then that surface coating/operation is not subject to this subpart.",
          "citations": [
            "40 CFR 63.4481(c)"
          ]
        },
        {
          "criterion": "If the application is performed using handheld, non-refillable aerosol containers, touch-up markers, or marking pens, then that activity is not a coating operation for purposes of this subpart.",
          "citations": [
            "40 CFR 63.4481(a)(1)"
          ]
        },
        {
          "criterion": "If the activities are part of the affected source (all coating operations as defined in § 63.4581 plus all storage, mixing, conveying equipment for coatings/thinners/additives/cleaning materials and waste handling), then they are within the scope of an affected source for this subpart.",
          "citations": [
            "40 CFR 63.4482(b)"
          ]
        },
        {
          "criterion": "If the equipment/operation was first constructed after December 4, 2002 according to the criteria in § 63.4482(c)(1)–(3), then the affected source is a new source (otherwise it may be existing or reconstructed), which affects which emission limits and requirements apply.",
          "citations": [
            "40 CFR 63.4482(c)"
          ]
        },
        {
          "criterion": "If the activity is limited to surface preparation or cleaning (use of a cleaning material/solvent to prepare a substrate or remove dried coating) and is not directly related to application of a coating, then that activity may not constitute a surface coating operation under this subpart.",
          "citations": [
            "40 CFR 63.4581",
            "40 CFR 63.4481(a)(1)"
          ]
        }
      ]
    }
  ],
  "checklist": [
    "Determine whether the methylene chloride application is intended to bond parts (i.e., functions as an adhesive) or instead is only cleaning/surface preparation (check purpose, process description, and expected residue—does it leave a film or solids?).",
    "Measure or estimate the annual volume of methylene chloride-containing materials and any other coatings/thinners/additives/cleaning materials used in these solvent-welding lines (liters or gallons per year).",
    "Determine whether the methylene chloride-containing material and any other materials used contain organic HAP (use supplier formulation data, Method 311, or Method 24 as applicable).",
    "Determine whether the facility is a major HAP source (potential to emit ≥10 tons/year of any single HAP or ≥25 tons/year total HAP); include emissions from these lines in that calculation.",
    "Verify whether the application method is exempt (handheld non-refillable aerosol, touch-up markers, marking pens) or is an industrial coating/adhesive application (not exempt) per § 63.4481(a)(1).",
    "Check whether any of the specific exemptions in § 63.4481(c)(1)–(17) apply to your operation (e.g., research/lab, hobby shop, only non-organic HAP coatings, product-specific NESHAP applicability overlaps).",
    "Identify all equipment and activities that would be part of the affected source per § 63.4482(b) (coating operations, storage/mixing vessels, conveying equipment, waste handling) to determine scope of coverage.",
    "If this is a new or modified installation, confirm construction/installation dates relative to Dec 4, 2002 and whether the criteria for a 'new' affected source in § 63.4482(c) are met.",
    "If you plan to use a compliance alternative (predominant activity, facility-specific limit, or choose another surface-coating NESHAP where allowed), document and calculate the basis per § 63.4481(e) and § 63.4490."
  ]
}

{
  "candidates": [
    {
      "subpart": "FFFFFF",
      "title": "Area-source NESHAP for Secondary Copper Smelters",
      "criteria": [
        {
          "criterion": "If your facility processes copper scrap in a blast furnace and converter or uses another pyrometallurgical purification process to produce anode copper from copper scrap (including low-grade scrap) and is an area source, then it is a secondary copper smelter and is subject to this subpart if it is a new affected source.",
          "citations": [
            "40 CFR 63.11158",
            "40 CFR 63.11153(a)",
            "40 CFR 63.11153(b)"
          ]
        },
        {
          "criterion": "If your facility merely melts recycled copper scrap or copper alloy scrap to produce ingots or for direct use in a manufacturing process (and does not produce anode copper by pyrometallurgical purification), then it is not a secondary copper smelter and this subpart does not apply.",
          "citations": [
            "40 CFR 63.11158"
          ]
        },
        {
          "criterion": "If the affected source commenced construction or reconstruction before October 6, 2006 then it is not a new affected source and the new-source provisions of this subpart do not apply.",
          "citations": [
            "40 CFR 63.11153(b)"
          ]
        }
      ]
    },
    {
      "subpart": "ZZZZZZ",
      "title": "Area-source NESHAP for Aluminum, Copper, and Other Nonferrous Foundries (Copper Foundries)",
      "criteria": [
        {
          "criterion": "If your facility is a copper foundry that melts copper and pours molten copper into molds to manufacture complex-shaped copper castings (not including primary or secondary metal producers that cast simple shapes such as anode copper) and is an area source meeting the annual metal melt production (existing) or annual metal melt capacity (new) threshold of at least 600 tons per year, then this subpart applies.",
          "citations": [
            "40 CFR 63.11556",
            "40 CFR 63.11544(a)(4)",
            "40 CFR 63.11544(b)"
          ]
        },
        {
          "criterion": "If your operations are those of a primary or secondary metal producer that cast molten copper to produce simple shapes such as sows, ingots, bars, rods, anode copper, or copper cake, then the facility is not a copper foundry and this subpart does not apply to those melting/casting operations.",
          "citations": [
            "40 CFR 63.11556"
          ]
        },
        {
          "criterion": "If you commenced construction or reconstruction of the melting operation after February 9, 2009, then determine applicability based on annual metal melt capacity at startup as described for new affected sources.",
          "citations": [
            "40 CFR 63.11544(a)(4)(ii)",
            "40 CFR 63.11544(d)"
          ]
        }
      ]
    },
    {
      "subpart": "TTTTTT",
      "title": "Area-source NESHAP for Secondary Nonferrous Metals Processing Facilities",
      "criteria": [
        {
          "criterion": "If you own or operate a secondary nonferrous metals processing facility that is an area source of HAP emissions, then you are subject to this subpart.",
          "citations": [
            "40 CFR 63.11462(a)"
          ]
        },
        {
          "criterion": "If you are an area source subject to this subpart, then you are (in general) exempt from the obligation to obtain a permit under 40 CFR part 70 or 71 solely because of area-source status but must continue to comply with the subpart's requirements.",
          "citations": [
            "40 CFR 63.11462(b)"
          ]
        }
      ]
    }
  ],
  "checklist": [
    "Does the facility process copper scrap using a pyrometallurgical purification process (e.g., smelting furnace, blast furnace, converter, or other melting/oxidation-reduction and fluxing steps) specifically to produce anode copper that is shipped off-site?",
    "Does the facility cast molten copper into anodes (anode copper) rather than into complex-shaped castings (i.e., are final products anodes/ingots/simple shapes vs. castings)?",
    "Is the furnace you operate a smelting furnace or melting furnace as described in the definitions (type: tilting anode furnace — characterize whether it functions as a pyrometallurgical smelter)?",
    "Was the affected source constructed/reconstructed on or after October 6, 2006 (for Subpart FFFFFF new-source test) and/or on or after February 9, 2009 (for Subpart ZZZZZZ new-source test)?",
    "Is the facility classified as an area source of HAPs (i.e., below major-source thresholds) under 40 CFR part 63 for the relevant HAPs?",
    "What is the facility's annual metal melt production (if existing) or annual metal melt capacity at startup (if new) for copper and other nonferrous metals, in tons per year (to compare to 600 tpy and 6,000 tpy thresholds)?",
    "What percentage and types of scrap are charged (confirm the 90% copper sorting and whether scrap contains oils, plastics, insulation, or other contaminants subject to the subpart's scrap-preparation work practice standard)?",
    "Do you plan to capture and control furnace and transfer fumes with a capture system and control device (baghouse or other), and what PM control approach will be used (baghouse + bag leak detection vs alternate control device requiring approved monitoring plan)?",
    "Will you be issuing/obtaining an operating permit under 40 CFR part 70 or 71 as required if subject to Subpart FFFFFF or otherwise required by permitting authorities?",
    "Confirm whether any operations involve sweating or burning insulation or other non-melting scrap-prep activities (the facility reports none; verify in practice and in scrap pretreatment plan)."
  ]
}

{
  "candidates": [
    {
      "subpart": "M",
      "title": "National Emission Standards for Perchloroethylene Dry Cleaning Facilities (Subpart M)",
      "criteria": [
        {
          "criterion": "If a dry cleaning facility uses perchloroethylene (PCE), then the provisions of this subpart apply to the owner or operator.",
          "citations": [
            "40 CFR 63.320(a)"
          ]
        },
        {
          "criterion": "If a dry cleaning system is located in a building with a residence after December 21, 2020, then the owner or operator shall eliminate any emission of PCE from that dry cleaning system.",
          "citations": [
            "40 CFR 63.322(o)(5)(i)"
          ]
        },
        {
          "criterion": "If a dry cleaning system was installed or relocated after December 21, 2005 and is located in a building with a residence, then the owner or operator must eliminate any emission of PCE from that system (per the post-2005 installation rule).",
          "citations": [
            "40 CFR 63.322(o)(4)"
          ]
        },
        {
          "criterion": "If you operate a coin-operated dry cleaning machine, then that machine is exempt from the requirements of this subpart (i.e., not subject to the subpart's requirements).",
          "citations": [
            "40 CFR 63.320(j)"
          ]
        },
        {
          "criterion": "If the facility emits or has the potential to emit more than 9.1 megagrams per year (10 tons per year) of PCE, or meets the specified yearly PCE consumption thresholds in §63.320(g), then the dry cleaning facility is a major source (otherwise it is an area source).",
          "citations": [
            "40 CFR 63.320(g)"
          ]
        },
        {
          "criterion": "If the total yearly PCE consumption (calculated per §63.323(d)) is less than 530 liters (140 gallons) per year under the conditions in paragraph (d), then certain machines/facilities are exempt from many sections of §§63.322–63.324 as specified in §63.320(d).",
          "citations": [
            "40 CFR 63.320(d)"
          ]
        },
        {
          "criterion": "If the facility includes only transfer machine system(s) and total yearly PCE consumption is less than 760 liters (200 gallons) per year, then certain exemptions apply as specified in §63.320(e).",
          "citations": [
            "40 CFR 63.320(e)"
          ]
        }
      ]
    },
    {
      "subpart": "A",
      "title": "General Provisions (Subpart A)",
      "criteria": [
        {
          "criterion": "If an affected source has a relevant standard established pursuant to section 112 of the Act, then the requirements in §63.6 apply to the owner or operator of that affected source.",
          "citations": [
            "40 CFR 63.6(a)(1)"
          ]
        },
        {
          "criterion": "If an existing source is subject to a standard established under this part, then the owner or operator shall comply with that standard by the compliance date established in the applicable subpart (and in no case will the compliance date established for an existing source exceed 3 years after the effective date of the standard).",
          "citations": [
            "40 CFR 63.6(c)(1)"
          ]
        },
        {
          "criterion": "If an affected source is subject to a relevant standard, then at all times the owner or operator must operate and maintain the source and associated control/monitoring equipment consistent with safety and good air pollution control practices to minimize emissions.",
          "citations": [
            "40 CFR 63.6(e)(1)(i)"
          ]
        }
      ]
    },
    {
      "subpart": "EEEE",
      "title": "Subpart EEEE (general requirements — excerpts)",
      "criteria": [
        {
          "criterion": "If equipment identified in §63.2338(b)(1)–(5) is in OLD operation, then you must be in compliance with the emission limitations, operating limits, and work practice standards in this subpart whenever that equipment is in OLD operation.",
          "citations": [
            "40 CFR 63.2350(a)"
          ]
        },
        {
          "criterion": "If you are subject to Subpart EEEE, then you must operate and maintain your affected source, including air pollution control and monitoring equipment, according to §63.6(e)(1)(i) (unless and until paragraph (d) of §63.2350 changes that obligation per the listed compliance dates).",
          "citations": [
            "40 CFR 63.2350(b)"
          ]
        },
        {
          "criterion": "If you are subject to Subpart EEEE, then you must develop a written startup, shutdown, and malfunction (SSM) plan per §63.6(e)(3) as required by this subpart, except as modified by the dates and exceptions in §63.2350(c)–(d).",
          "citations": [
            "40 CFR 63.2350(c)",
            "40 CFR 63.2350(d)"
          ]
        },
        {
          "criterion": "If you are subject to Subpart EEEE, then Table 12 to that subpart identifies which parts of the General Provisions (§§63.1–63.15) apply to you.",
          "citations": [
            "40 CFR 63.2398"
          ]
        }
      ]
    }
  ],
  "checklist": [
    "Do you use perchloroethylene (PCE) in your dry cleaning operations?",
    "Is the dry cleaning facility located in a building that includes any residence(s), including residences that are currently vacant? (see 40 CFR 63.324(f)(3))",
    "Is the dry cleaning machine coin-operated?",
    "What type of machine do you operate: dry-to-dry or a transfer machine system (washer + dryer/reclaimer)?",
    "What is the date the dry cleaning machine was constructed, reconstructed, installed, or relocated (to determine whether it was installed/relocated after Dec 21, 2005 or other compliance-date triggers)?",
    "What is the facility's total yearly PCE consumption (sum of purchases over the prior 12 months, calculated per 40 CFR 63.323(d))?",
    "Based on yearly PCE consumption, does the facility meet any exemption thresholds (e.g., <530 L/yr per §63.320(d), <760 L/yr per §63.320(e)) or the major-source thresholds in §63.320(g)?",
    "Do you currently eliminate PCE emissions during transfer and at door opening (e.g., refrigerated condenser and/or non-vented carbon adsorber configured per §63.322 and monitored per §63.323)?",
    "Do you have monitoring and records required by §63.323 and the purchase/consumption logs and notification/recordkeeping required by §63.324 (including the notification in §63.324(f) identifying if the facility is located in a building with a residence)?",
    "If subject to Subpart EEEE, is your equipment identified in §63.2338(b)(1)–(5) and are you following the General Provisions that apply (see Table 12 per §63.2398) and the SSM/operation requirements in §63.2350 and §63.6(e)(1)(i)?"
  ]
}

{
  "candidates": [
    {
      "subpart": "LLL",
      "title": "National Emission Standards for Hazardous Air Pollutants for Portland Cement Plants (NESHAP, Subpart LLL)",
      "criteria": [
        {
          "criterion": "If the facility is a portland cement plant that is a major source or an area source, then this subpart applies to each kiln including inline coal mills.",
          "citations": [
            "40 CFR 63.1340(a)",
            "40 CFR 63.1340(b)(1)"
          ]
        },
        {
          "criterion": "If a coal mill uses kiln exhaust gases (i.e., is an in-line coal mill), then it is considered part of the kiln and is subject to the kiln emissions limits and monitoring requirements of this subpart.",
          "citations": [
            "40 CFR 63.1341 (definition of in-line coal mill)",
            "40 CFR 63.1340(b)(1)"
          ]
        },
        {
          "criterion": "If kiln gases are diverted to a coal mill that exhausts through a separate stack, then the combined PM emissions from the kiln and the coal mill stack are subject to the kiln PM emissions limit and must be accounted for in compliance calculations.",
          "citations": [
            "40 CFR 63.1343(b)(2)"
          ]
        },
        {
          "criterion": "If kiln gases are diverted to a coal mill that exhausts through a separate stack, then initial and subsequent performance testing must include simultaneous testing of the kiln and coal mill stacks and calculation of the combined PM emission rate for each test run.",
          "citations": [
            "40 CFR 63.1349(b)(1)(viii)"
          ]
        },
        {
          "criterion": "If subject to PM limits under this subpart, then initial compliance must be demonstrated using Method 5 or 5I and continuous compliance must be demonstrated by operating a PM continuous parametric monitoring system (PM CPMS) with annual (or required) performance tests and establishment of a site-specific operating limit.",
          "citations": [
            "40 CFR 63.1349(b)(1)",
            "40 CFR 63.1350(b)(1)"
          ]
        },
        {
          "criterion": "If kiln gases are diverted to a coal mill that exhausts through a separate stack, then kiln-specific THC and HCl limits must be calculated using the flow-weighted equations that include the coal mill stack (and THC/HCl must be measured either upstream of the coal mill or in the coal mill stack) for establishing compliance limits.",
          "citations": [
            "40 CFR 63.1349(b)(4)(iii)",
            "40 CFR 63.1349(b)(4)(iv)",
            "40 CFR 63.1349(b)(6)(iv)",
            "40 CFR 63.1350(i)",
            "40 CFR 63.1350(l)"
          ]
        },
        {
          "criterion": "If subject to mercury limits and kiln gases are diverted to a coal mill that exhausts through a separate stack, then you must account for mercury emitted from the coal mill by conducting performance tests on the coal mill/alkali bypass stacks (Method 29 or 30B as specified), develop hourly mercury mass emissions for those stacks, and sum kiln + coal mill emissions to determine the 30-day rolling average per clinker production while operating the required Hg CEMS or sorbent-trap monitoring system.",
          "citations": [
            "40 CFR 63.1349(b)(5)",
            "40 CFR 63.1350(k)(5)(i)",
            "40 CFR 63.1350(k)(5)(ii)",
            "40 CFR 63.1350(k)(5)(iii)"
          ]
        },
        {
          "criterion": "If an onsite source is subject to the standards for nonmetallic mineral processing plants in subpart OOO of 40 CFR part 60, then that onsite source is not subject to this subpart.",
          "citations": [
            "40 CFR 63.1340(c)"
          ]
        },
        {
          "criterion": "If the coal mill exhaust is commingled with the kiln exhaust in a single stack, then you may demonstrate compliance either by testing the commingled stream or by testing the kiln exhaust prior to reintroduction and separately testing the diverted stream and adding all emissions for each pollutant.",
          "citations": [
            "40 CFR 63.1348(b)(7)"
          ]
        }
      ]
    }
  ],
  "checklist": [
    "Is the facility a portland cement plant and is it a major source or an area source (per 40 CFR 63.2)?",
    "Does the coal mill use kiln exhaust gases (i.e., does it meet the subpart LLL definition of an in-line coal mill) or does it have its own independent heat source?",
    "Does the coal mill exhaust through a separate stack, or are its exhausts commingled with the kiln/clinker cooler exhaust before the PM control device?",
    "If the coal mill has a separate stack: what are the stack flow rates (Qcm) and are there sampling ports for Method 5/25A/321/29/30B as needed?",
    "Which air pollutants/limits apply at the kiln (PM, D/F, THC/total organic HAP, HCl, Hg) for this kiln (new vs existing, major vs area) per Table 1 in 63.1343?",
    "What PM control device(s) serve the kiln and/or coal mill (baghouse/ESP/wet scrubber) and are control device inlets/outlets combined or separate?",
    "Are there existing CEMS/CPMS: PM CPMS, THC CEMS, HCl CEMS or HCl/SO2 CPMS alternative, Hg CEMS or sorbent trap system, and are they installed upstream of the coal mill or at the coal mill stack as appropriate?",
    "If demonstrating HCl or THC compliance, can you measure upstream of the coal mill or in the coal mill stack and do you have the necessary spans/calibrations per §63.1350(i)/(l)?",
    "Is the coal mill (or any onsite equipment) already subject to an NSPS or subpart OOO of 40 CFR part 60 (nonmetallic mineral processing) that might exclude it from Subpart LLL under §63.1340(c)?",
    "Can you operate/measure clinker production and stack flow continuously and with the accuracy required (weigh scales, flow monitors) to calculate lb/ton-clinker emissions and 30-operating-day rolling averages per §63.1350(d) and (n)?",
    "Do you have the capability to perform simultaneous performance tests (Method 5/5I for PM, Method 25A for THC, Method 321 for HCl, Method 29/30B for Hg, Method 23 for D/F, Method 18/320 for organic HAP) on kiln and coal mill stacks and to calculate flow-weighted, combined emissions as required?",
    "Are control-device parameter monitors (e.g., sorbent injection rate, carrier gas flow/pressure, scrubber pressure/pH, bag leak detection) installed and capable of meeting the CPMS requirements referenced in the subpart?",
    "If relying on alternative monitoring (e.g., SO2 CEMS for HCl), have you prepared the data/information to support an alternate monitoring application per §63.1350(o)?"
  ]
}

{
  "candidates": [
    {
      "subpart": "HHHHHH",
      "title": "Area Source Paint Stripping and Miscellaneous Surface Coating (Autobody/Motor Vehicle and Target HAP coatings)",
      "criteria": [
        {
          "criterion": "If you are an area source of HAP and you perform spray application of coatings to motor vehicles and mobile equipment, then you are subject to this subpart.",
          "citations": [
            "40 CFR 63.11170(a)(2)",
            "40 CFR 63.11169(b)"
          ]
        },
        {
          "criterion": "If you are an area source of HAP and you perform spray application of coatings that contain the target HAP to a plastic and/or metal substrate on a part or product (excluding facility maintenance or space vehicle), then you are subject to this subpart.",
          "citations": [
            "40 CFR 63.11170(a)(3)",
            "40 CFR 63.11180 (Target HAP / Target HAP containing coating definition)"
          ]
        },
        {
          "criterion": "If you are the owner or operator of a motor vehicle or mobile equipment surface coating operation and you spray apply no coatings that contain the target HAP and you submit the required petition or notification to the Administrator demonstrating you do not spray apply any target HAP-containing coatings, then you may be exempt from the surface coating provisions of this subpart (subject to Administrator verification).",
          "citations": [
            "40 CFR 63.11170(a)(2)",
            "40 CFR 63.11180 (Target HAP / Target HAP containing coating definition)"
          ]
        },
        {
          "criterion": "If your source is not an area source (i.e., is a major source, is located at a major source, or is part of a major source of HAP), then this area-source subpart does not apply.",
          "citations": [
            "40 CFR 63.11170(b)"
          ]
        },
        {
          "criterion": "If the surface coating or paint stripping meets any of the exclusions in §63.11169(d) (for example research and laboratory activities, quality control activities, or activities covered under another area-source NESHAP), then this subpart does not apply to those activities.",
          "citations": [
            "40 CFR 63.11169(d)"
          ]
        }
      ]
    },
    {
      "subpart": "MMMM",
      "title": "Surface Coating of Miscellaneous Metal Parts and Products (Miscellaneous Metal Parts NESHAP)",
      "criteria": [
        {
          "criterion": "If you own or operate an affected source that uses 946 liters (250 gallons) per year or more of coatings that contain HAP in the surface coating of miscellaneous metal parts and products and that source is a major source (or is located at or part of a major source of HAP), then you are subject to this subpart.",
          "citations": [
            "40 CFR 63.3881(b)"
          ]
        },
        {
          "criterion": "If your coating operation uses only coatings, thinners, and cleaning materials that contain no organic HAP (as determined under the referenced methods), then this subpart does not apply to your coating operation.",
          "citations": [
            "40 CFR 63.3881(c)(1)"
          ]
        },
        {
          "criterion": "If coatings used in a given coating category are in volumes of less than 189 liters (50 gallons) per year and the total volume of coatings exempt under this paragraph does not exceed 946 liters (250 gallons) per year at the facility, then this subpart does not apply to those coating activities under that paragraph.",
          "citations": [
            "40 CFR 63.3881(c)(3)"
          ]
        },
        {
          "criterion": "If your polyurea/spray line is part of the affected source as defined (all coating operations, storage, conveyance, and waste handling associated with surface coating of miscellaneous metal parts and products), then that line is included within the affected source scope for this subpart.",
          "citations": [
            "40 CFR 63.3882(b)"
          ]
        },
        {
          "criterion": "If your surface coating activity meets any of the other exclusions or product-specific exceptions listed in §63.3881(c)(2) through (c)(17) (for example product categories subject to other surface coating NESHAPs, certain web or coil coating processes, aerospace, shipbuilding, etc.), then this subpart does not apply for those activities.",
          "citations": [
            "40 CFR 63.3881(c)"
          ]
        }
      ]
    }
  ],
  "checklist": [
    "Confirm whether the facility is an area source or a major source of HAP (calculate actual and potential HAP emissions vs. 10 t/yr single HAP or 25 t/yr total HAP).",
    "For the polyurea spray line, determine whether coatings are spray-applied as defined (hand-held or spray gun atomizing device) and whether the substrates are metal or plastic.",
    "Identify whether the polyurea line coats assembled motor vehicles or mobile equipment (autobody/mobile equipment) or miscellaneous metal parts/products that are not motor vehicles.",
    "Obtain and review manufacturer formulation data / MSDS for the polyurea coating as received and determine whether it contains any target HAP (Cr, Pb, Mn, Ni, Cd) at or above the thresholds in 40 CFR 63.11180 (>=0.1% for carcinogenic target HAPs (Cr, Cd, Pb, Ni) and >=1.0% for Mn).",
